import Foundation
import WTRLCore
public enum SanTrianaTerrainType:String,Codable,Sendable { case highElevationTarChip,urbanRuttedAsphalt,polishedHarborConcrete,bridgeDeck,industrialGravel }
public struct WorldChunkCoordinate:Hashable,Codable,Sendable { public var x:Int,z:Int;public init(x:Int,z:Int){self.x=x;self.z=z} }
public struct StreamingDelta:Sendable { public var load:Set<WorldChunkCoordinate>,evict:Set<WorldChunkCoordinate>,resident:Set<WorldChunkCoordinate> }
public enum SanTrianaStreamingAuthority { public static let chunkSizeM=250.0; public static func coordinate(x:Double,z:Double)->WorldChunkCoordinate{.init(x:Int(floor(x/chunkSizeM)),z:Int(floor(z/chunkSizeM)))}; public static func desired(around c:WorldChunkCoordinate,radius:Int=2)->Set<WorldChunkCoordinate>{var s=Set<WorldChunkCoordinate>();for x in -radius...radius {for z in -radius...radius{s.insert(.init(x:c.x+x,z:c.z+z))}};return s}; public static func page(current:Set<WorldChunkCoordinate>,player:WorldChunkCoordinate,radius:Int=2)->StreamingDelta{let want=desired(around:player,radius:radius);return .init(load:want.subtracting(current),evict:current.subtracting(want),resident:want)} }
public struct AcousticReflection:Codable,Hashable,Sendable { public var delayS:Double,gain:Double,lowPassHz:Double }
public enum EnvironmentalAcousticAuthority { static func sub(_ a:Vector3D,_ b:Vector3D)->Vector3D{.init(a.x-b.x,a.y-b.y,a.z-b.z)}; static func normalized(_ v:Vector3D)->Vector3D{let m=max(v.magnitude,1e-9);return .init(v.x/m,v.y/m,v.z/m)}; static func dot(_ a:Vector3D,_ b:Vector3D)->Double{a.x*b.x+a.y*b.y+a.z*b.z}; public static func reflections(vehicle:Vector3D,exhaustDirection:Vector3D,walls:[Vector3D])->[AcousticReflection]{ let dir=normalized(exhaustDirection);return walls.compactMap{w in let d=sub(w,vehicle),dist=d.magnitude;guard dist>2 && dist<48 else{return nil};let alignment=max(0.08,dot(dir,normalized(d)));return .init(delayS:2*dist/343,gain:alignment/(1+0.18*dist),lowPassHz:max(1400,16000-280*dist))}.sorted{$0.gain>$1.gain}.prefix(6).map{$0} } }
